'use strict';

const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));

function parseDiff(input) {
  const lines = String(input == null ? '' : input).replace(/\r/g, '').split('\n');
  if (!lines.some((x) => /^diff --git\s/.test(x) || /^@@/.test(x) || /^[+\-]\S/.test(x))) return null;
  return lines.map((text) => ({
    kind: /^\+(?!\+\+\+)/.test(text) ? 'add' : /^-(?!\-\-\-)/.test(text) ? 'remove' : /^(diff --git|index |--- |\+\+\+ |@@)/.test(text) ? 'meta' : 'context',
    text,
  }));
}

function inlineMd(v) {
  let s = esc(v);
  s = s.replace(/\[([^\]]+)\]\(([^\s)]+)(?:\s+"[^"]*")?\)/g, (m, label, href) => {
    const safe = /^(?:https?:|mailto:|\/|#)/i.test(href) ? href : '#';
    const ext = /^(?:https?:|mailto:)/i.test(safe) ? ' target="_blank" rel="noopener noreferrer"' : '';
    return '<a href="' + esc(safe) + '"' + ext + '>' + label + '</a>';
  });
  return s.replace(/`([^`\n]+)`/g, '<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>').replace(/__([^_\n]+)__/g, '<strong>$1</strong>').replace(/\*([^*\n]+)\*/g, '<em>$1</em>');
}

function renderDiff(input) {
  const rows = parseDiff(input);
  if (!rows) return '<pre><code>' + esc(input) + '</code></pre>';
  return '<div class="diff" role="group" aria-label="Code diff">' + rows.map((r) => '<div class="diff-row ' + r.kind + '" aria-label="' + (r.kind === 'add' ? 'added line' : r.kind === 'remove' ? 'deleted line' : r.kind === 'meta' ? 'diff metadata' : 'context line') + '"><span class="diff-sign" aria-hidden="true">' + (r.kind === 'add' ? '+' : r.kind === 'remove' ? '−' : ' ') + '</span><code>' + esc(r.text) + '</code></div>').join('') + '</div>';
}

function md(source) {
  const lines = String(source == null ? '' : source).replace(/\r/g, '').split('\n');
  const out = []; let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) { i++; continue; }
    const fence = line.match(/^```\s*([\w-]*)\s*$/);
    if (fence) {
      const lang = fence[1] || '', body = []; i++;
      while (i < lines.length && !/^```\s*$/.test(lines[i])) body.push(lines[i++]);
      if (i < lines.length) i++;
      const code = body.join('\n');
      out.push(lang === 'diff' ? renderDiff(code) : '<pre><code' + (lang ? ' class="language-' + esc(lang) + '"' : '') + '>' + esc(code) + '</code></pre>');
      continue;
    }
    const heading = line.match(/^(#{1,3})\s+(.+)$/);
    if (heading) { out.push('<h' + heading[1].length + '>' + inlineMd(heading[2]) + '</h' + heading[1].length + '>'); i++; continue; }
    if (/^[-*_]{3,}\s*$/.test(line)) { out.push('<hr>'); i++; continue; }
    if (/^>\s?/.test(line)) { const a=[]; while (i < lines.length && /^>\s?/.test(lines[i])) a.push(lines[i++].replace(/^>\s?/,'')); out.push('<blockquote>' + inlineMd(a.join('\n')).replace(/\n/g,'<br>') + '</blockquote>'); continue; }
    if (/^\s*[-*+]\s+/.test(line) || /^\s*\d+[.)]\s+/.test(line)) {
      const ordered = /^\s*\d+[.)]\s+/.test(line), a = [], re = ordered ? /^\s*\d+[.)]\s+/ : /^\s*[-*+]\s+/;
      while (i < lines.length && re.test(lines[i])) a.push(lines[i++].replace(re,''));
      out.push('<' + (ordered ? 'ol' : 'ul') + '>' + a.map((x) => '<li>' + inlineMd(x) + '</li>').join('') + '</' + (ordered ? 'ol' : 'ul') + '>'); continue;
    }
    if (line.includes('|') && i + 1 < lines.length && /^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(lines[i + 1])) {
      const cells = (x) => x.replace(/^\s*\|/,'').replace(/\|\s*$/,'').split('|').map((c) => c.trim());
      const head = cells(line); i += 2; const rows = [];
      while (i < lines.length && lines[i].includes('|') && lines[i].trim()) rows.push(cells(lines[i++]));
      out.push('<div class="table-wrap"><table><thead><tr>' + head.map((x) => '<th scope="col">' + inlineMd(x) + '</th>').join('') + '</tr></thead><tbody>' + rows.map((r) => '<tr>' + head.map((_, n) => '<td>' + inlineMd(r[n] || '') + '</td>').join('') + '</tr>').join('') + '</tbody></table></div>'); continue;
    }
    const para = [line]; i++;
    while (i < lines.length && lines[i].trim() && !/^```/.test(lines[i]) && !/^(#{1,3})\s+/.test(lines[i]) && !/^\s*[-*+]\s+/.test(lines[i])) para.push(lines[i++]);
    out.push('<p>' + inlineMd(para.join('\n')).replace(/\n/g,'<br>') + '</p>');
  }
  return out.join('');
}

